package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class HospitalService{private final HospitalRepository r;public HospitalService(HospitalRepository r){this.r=r;} private Hospital find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Hospital not found"));} private HospitalDTO dto(Hospital e){return HospitalDTO.builder().id(e.getId()).name(e.getName()).location(e.getLocation()).build();} private void apply(Hospital e,HospitalDTO d){e.setName(d.getName());e.setLocation(d.getLocation());} public HospitalDTO create(HospitalDTO d){Hospital e=new Hospital();apply(e,d);return dto(r.save(e));} public List<HospitalDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public HospitalDTO get(Long id){return dto(find(id));} public HospitalDTO update(Long id,HospitalDTO d){Hospital e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Hospital e=find(id);e.setIsActive(false);r.save(e);}}
